const M=WalletModel;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=n=>'¥ '+fmt(n);
const STORE='crossborder-wallet-prototype-v1';
let S;try{S=JSON.parse(localStorage.getItem(STORE));}catch{}if(!S||S.version!==1)S=M.seed();S=M.upgrade(S);
let C={page:'home',mode:'app',stage:0,fields:{},tab:'order',flow:'transfer',scenario:'normal',privacy:false};
let popup=false,modalState=null,toastTimer,returnToPay=null;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(S));}catch{}}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',wallet:'M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m18 7h-6v4h6M16 15h1',down:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',up:'M12 17V4m-5 5 5-5 5 5M4 17v4h16v-4',pay:'M3 7h18v13H3ZM3 11h18M6 16h4M6 3h12',bank:'m3 8 9-5 9 5ZM5 11v7m5-7v7m4-7v7m5-7v7M3 21h18',exchange:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',settings:'M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-4-1V8l4-1Zm3 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',list:'M6 3h12v18H6ZM9 7h6M9 11h6M9 15h4',gift:'M3 9h18v4H3ZM5 13v8h14v-8M12 9v12M12 9C3 9 5 1 9 4l3 5Zm0 0c9 0 7-8 3-5Z',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M9 8a3 3 0 1 1 5 2c-1 1-2 1-2 3m0 4h.01',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4M12 2v2',chevron:'m9 5 7 7-7 7',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 11v6m0-10h.01',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Zm-4 9 3 3 5-5',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 6v6l4 3',globe:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M2 12h20M12 2c6 6 6 14 0 20M12 2c-6 6-6 14 0 20',box:'m12 2 9 5v10l-9 5-9-5V7Zm-9 5 9 5 9-5M12 12v10M7 4l10 6',plus:'M12 4v16M4 12h16',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16m6-2 6 6',refresh:'M20 7A9 9 0 1 0 21 15M20 2v5h-5',sortup:'m6 14 6-6 6 6',sortdown:'m6 9 6 6 6-6',flow:'M3 4h6v5H3ZM15 15h6v5h-6M6 9v9h9M9 6h9v9',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',copy:'M8 8h13v13H8ZM16 8V3H3v13h5',link:'M10 14 14 10M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',download:'M12 3v13m-5-5 5 5 5-5M4 20h16',card:'M3 5h18v14H3ZM3 10h18M6 15h3',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'};
function icon(n){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.wallet}"/></svg>`;}
function b(text,action,cls='',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function link(text,action,attrs=''){return `<button type="button" class="textbtn" data-action="${action}" ${attrs}>${text}</button>`;}
function tag(text,type=''){return `<span class="tag ${type}">${text}</span>`;}
function note(text,type=''){return `<div class="notice ${type}">${icon(type==='success'?'check':'info')}<div>${text}</div></div>`;}
function kv(k,v,cls=''){return `<div class="kv ${cls}"><span class="key">${k}</span><span class="val">${v}</span></div>`;}
function head(title,subtitle='',right=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="headright">${right}</div></div>`;}
function field(label,name,value='',help='',attrs=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${esc(value)}" ${attrs}>${help?`<div class="help">${help}</div>`:''}</div>`;}
function select(label,name,values,current){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(x=>`<option value="${esc(x[0])}" ${current===x[0]?'selected':''}>${esc(x[1])}</option>`).join('')}</select></div>`;}
function amountField(label,name,value,currency,help='',max=false){return `<div class="field"><label for="${name}">${label}</label><div class="money-input"><input id="${name}" name="${name}" value="${esc(value)}" inputmode="decimal" placeholder="0.00" autocomplete="off">${max?link('全部','max'):''}<span class="unit">${currency}</span></div>${help?`<div class="help">${help}</div>`:''}</div>`;}
function steps(names,active){return `<div class="steps">${names.map((x,i)=>`${i?'<div class="step-line"></div>':''}<div class="step ${i===active?'active':i<active?'done':''}"><span>${i<active?'✓':i+1}</span>${x}</div>`).join('')}</div>`;}
function error(){return C.error?`<div class="error-text" role="alert">${esc(C.error)}</div>`:'';}
function num(name){const x=String(C.fields[name]??'').trim();if(!/^\d+(\.\d{1,2})?$/.test(x))return NaN;return Number(x);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function fresh(page,options={}){if(page==='pay')page='home';C={...C,page,mode:'app',stage:0,fields:{},error:'',quote:null,record:null,scenario:'normal',...options};if(page==='transfer')C.fields={source:'intl',currency:'USD',amount:'1000',...C.fields};if(page==='transferout')C.fields={destination:'acp',currency:'USD',amount:'1000',...C.fields};if(page==='withdraw')C.fields={currency:'CNY',bank:'b1',amount:'5000',...C.fields};if(page==='fx')C.fields={from:'USD',to:'CNY',amount:'1000',...C.fields};if(page==='settings'){C.draft=JSON.parse(JSON.stringify(S.settings));C.authDraft={wallet:true,acp:S.accounts.acp.authorized,intl:S.accounts.intl.authorized};}popup=false;render();window.scrollTo(0,0);}
function nav(page,options={}){fresh(page,options);history.replaceState(null,'','#'+page);}
function addTx(data){const record={id:'CB'+Date.now().toString().slice(-12),time:'2026-11-08 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}),...data};S.tx.unshift(record);persist();C.record=record;return record;}
const navs=[['home','wallet','钱包总览'],['transfer','down','转入'],['transferout','up','转出'],['withdraw','up','提现'],['fx','exchange','汇兑'],['records','list','资金明细']];
function shell(content){return `<header class="topbar"><div class="brand"><span class="brandmark"><em>e</em> 阿里国际站</span><span class="divider brandcontext"></span><span class="brandcontext">商家工作台</span></div><div class="topright">${tag('交互原型 · 演示数据','orange')}<button class="iconbtn" aria-label="消息提醒" data-action="notifications">${icon('bell')}</button><button class="iconbtn" aria-label="帮助中心" data-nav="help">${icon('help')}</button><span class="divider"></span><span class="tiny company">杭州远帆贸易有限公司</span><button class="avatar" data-action="profile" aria-label="商家账户">远帆</button></div></header><aside class="sidebar"><div class="workspace"><div class="square">${icon('wallet')}</div><div><b style="font-size:14px">资金管理</b><div class="eyebrow" style="margin-top:3px;font-size:8px">BUSINESS WALLET</div></div></div><div class="navsection">跨境宝</div>${navs.map(([id,ic,n])=>`<button class="navitem ${C.page===id&&C.mode==='app'?'active':''}" data-nav="${id}">${icon(ic)}<span>${n}</span></button>`).join('')}<div class="navsection" style="margin-top:15px">服务</div><button class="navitem ${C.page==='benefits'?'active':''}" data-nav="benefits">${icon('gift')}<span>权益中心</span></button><button class="navitem ${C.page==='help'?'active':''}" data-nav="help">${icon('help')}<span>帮助中心</span></button><div class="sidebottom"><div class="sidehelp"><b>${icon('shield')} 资金动态，清晰可查</b>每一笔收付都有迹可循</div><div class="tiny muted" style="text-align:center;margin-top:18px;font-size:9px">Alibaba.com Pay × 1688</div></div></aside><div class="proto"><div class="prototabs"><button class="${C.mode==='app'?'active':''}" data-mode="app">体验原型</button><button class="${C.mode==='flow'?'active':''}" data-mode="flow">用户动线</button><button class="${C.mode==='spec'?'active':''}" data-mode="spec">设计说明</button></div><div class="protohint"><i class="dot"></i><span>PC 端 · 所有操作均为模拟</span><span>V1.2 / 2026.11</span></div></div><main class="main ${C.mode!=='app'?'review':''}">${content}</main><div class="designbar"><button data-action="scenario">${icon('flow')} 情景演示</button><span style="color:#dbe2ed">|</span><button data-action="reset">${icon('refresh')} 重置</button></div>${popup?scenarioPopover():''}`;}
function render(){const views={home,transfer:transferPage,transferout:transferOutPage,withdraw:withdrawPage,fx:fxPage,settings:settingsPage,records:recordsPage,benefits:benefitsPage,help:helpPage};$('#app').innerHTML=shell(C.mode==='flow'?flowPage():C.mode==='spec'?specPage():(views[C.page]||home)());}
function sourceCard(id){const a=S.accounts[id],val=M.equivalent(a.balances),isWallet=id==='wallet';return `<div class="account-card"><div class="account-top"><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span>${a.name}${id==='acp'?'<span class="tiny muted" style="font-weight:400">Alibaba Pay</span>':''}${tag(isWallet?'钱包账户':a.authorized?'已授权':'已关闭',isWallet?'blue':a.authorized?'green':'orange')}</div><div class="tiny muted">${isWallet?'钱包可用余额':'可调用余额'} · 折合 CNY</div><div class="account-value mono ${C.privacy?'privacy':''}">${fmt(a.authorized?val:0)}</div><div class="currency-line ${C.privacy?'privacy':''}">${Object.entries(a.balances).filter(([c,n])=>n).map(([c,n])=>`<span>${c} ${fmt(n)}</span>`).join('')}</div><div class="account-bottom"><span>${isWallet?'资金存放于跨境宝':'资金仍留在'+a.name+'账户'}</span>${link(a.authorized?'查看明细 '+icon('chevron'):'管理授权 '+icon('chevron'),'account',`data-id="${id}"`)}</div></div>`;}
function txTable(rows,compact=false){return `<div class="table-wrap"><table><thead><tr><th>交易内容</th>${compact?'':'<th>资金账户</th>'}<th>金额</th><th>状态</th><th></th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><div class="title">${esc(t.title)}</div><div class="sub">${esc(t.time)}</div></td>${compact?'':`<td>${esc(S.accounts[t.source]?.name||'跨境宝')}</td>`}<td class="mono ${['收款','转入'].includes(t.type)?'green':''}">${esc(t.display)}</td><td><span class="${t.status==='已完成'?'green':t.status.includes('失败')||t.status==='已退回'?'red':'orange'} tiny"><i class="status-dot"></i>${esc(t.status)}</span></td><td>${link('详情','tx',`data-id="${t.id}"`)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">没有符合条件的记录</div></td></tr>'}</tbody></table></div>`;}
function home(){const w=S.accounts.wallet,usable=M.equivalent(w.balances),frozen=M.equivalent(w.frozen),balance=M.round(usable+frozen);return `${head('跨境宝','外销收入，灵活调度。',`<span class="sync-state">${icon('refresh')} 资金已同步 · 刚刚</span>`)}<section class="wallet-panel"><div class="wallet-panel-top"><span>${icon('shield')} 企业资金账户 <span class="wallet-status">正常</span></span>${b(icon('settings')+' 支付管理','go-settings','wallet-manage')}</div><div class="wallet-metrics"><div class="wallet-stat wallet-balance"><div class="wallet-stat-label">账户余额 <span>折合 CNY</span><button class="iconbtn" data-action="privacy" aria-label="显示或隐藏金额">${icon('eye')}</button></div><div class="wallet-number mono ${C.privacy?'privacy':''}"><small>¥</small>${fmt(balance)}</div><div class="wallet-stat-note ${C.privacy?'privacy':''}">可用 ¥ ${fmt(usable)} <span>冻结 ¥ ${fmt(frozen)}</span></div></div><div class="wallet-stat"><div class="wallet-stat-label">我的费率</div><div class="wallet-number mono">0.125<small>%</small></div><div class="wallet-stat-note">采购服务费 ${link('查看权益 '+icon('chevron'),'go-benefits')}</div></div><div class="wallet-stat wallet-quota"><div class="wallet-stat-label">可采购额度 <span>折合 CNY</span><button class="iconbtn quota-info" data-action="quota" aria-label="查看可采购额度构成" title="查看可采购额度构成">${icon('info')}</button></div><div class="wallet-number mono ${C.privacy?'privacy':''}"><small>¥</small>${fmt(M.available(S))}</div><div class="wallet-stat-note">跨境宝 + ACP + 国际站可调用余额</div></div></div><div class="wallet-operations">${[['transfer','down','转入','多渠道资金转入'],['transferout','up','转出','转至 ACP / 国际站'],['withdraw','bank','提现','提至同名企业银行卡'],['fx','exchange','汇兑','钱包内多币种兑换']].map(([id,ic,t,sub],i)=>`<button class="wallet-operation ${i===0?'emphasized':''}" data-nav="${id}"><span class="operation-icon">${icon(ic)}</span><span><strong>${t}</strong><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div></section><div class="sectionhead"><h2>我的资金账户 <span class="meta">统一使用，分别记账</span></h2><span class="tiny muted">金额按演示汇率折合 CNY</span></div><div class="account-grid">${['wallet','acp','intl'].map(sourceCard).join('')}</div><div class="lower-grid"><section class="panel flush"><div class="panel-title"><h2>最近资金动态</h2>${link('全部明细 '+icon('chevron'),'go-records')}</div>${txTable(S.tx.slice(0,4),true)}</section><aside><section class="panel" style="padding:22px"><div class="sectionhead"><h2>资金提醒</h2>${tag('1','orange')}</div><div class="task-item"><div class="task-icon">${icon('clock')}</div><div><h4>国际站待结算收款</h4><p>USD 3,000.00 · 结算后可用</p></div>${link(icon('chevron'),'pending-funds','aria-label="查看待结算资金"')}</div><div class="divider-line"></div><h3 style="font-size:13px;margin-bottom:12px">常用服务</h3><div class="service-links">${link(icon('bank')+' 我的银行卡','banks')}${link(icon('gift')+' 权益中心','go-benefits')}</div></section></aside></div><div class="design-note">账户余额展示跨境宝账面资金；可采购额度合计三个账户已授权的可用余额，冻结与待结算资金、银行卡余额不计入。金额、费率均为演示数据。</div>`;}
function transferPage(){const f=C.fields,src=f.source||'intl',a=S.accounts[src];if(C.stage===3)return resultPage();if(C.stage===0)return `${head('转入','连接多渠道收款，让资金在一个钱包里协同。',b('转入记录','transfer-records','',`aria-label="查看转入记录"`))}${steps(['选择资金来源','填写转入信息','确认与结果'],0)}<div class="form-layout"><section class="panel form-panel"><h2 style="margin-bottom:9px">资金从哪里来？</h2><p class="tiny muted" style="margin-bottom:24px">可保留原账户余额用于采购，也可主动转入跨境宝。</p><div class="choice-grid">${[['intl','a','阿里国际站','转入已结算的外销货款'],['acp','AP','ACP 余额','Alibaba Pay 收款工具余额'],['bank','card','银行转账','企业同名银行账户汇入'],['channel','globe','其他收款渠道','连接其他平台或 PSP 收款']].map(([id,ic,n,sub])=>`<button class="choice" data-action="transfer-select" data-id="${id}"><span class="source-icon ${id}">${['card','globe'].includes(ic)?icon(ic):ic}</span><div><h3>${n}</h3><p>${sub}</p></div>${icon('chevron')}</button>`).join('')}</div>${note('国际站和 ACP 已授权的可用余额，未转入跨境宝也能直接采购。账户间转入只改变钱存放的位置，总资产不增加。')}<div class="sectionhead"><h3 style="font-size:13px">收款入账规则</h3>${link('渠道授权管理 '+icon('chevron'),'go-settings')}</div>${kv('国际站新到账资金',S.settings.route.intl==='keep'?'保留原账户，可用于采购':'结算后自动转入跨境宝')}${kv('ACP 新到账资金',S.settings.route.acp==='keep'?'保留原账户，可用于采购':'结算后自动转入跨境宝')}</section><aside class="panel side-info"><h3>收款之后，资金怎么走？</h3><div class="timeline"><div class="timeline-item">客户付款或平台结算<p>关联外销订单、收款单</p></div><div class="timeline-item">到达对应渠道账户<p>处理中和待结算资金单独展示</p></div><div class="timeline-item">成为可用余额<p>完成结算且可支配后，更新可采购额度</p></div><div class="timeline-item">按你的规则使用<p>留在原账户，或转入跨境宝</p></div></div></aside></div>`;
if(src==='bank')return bankTransferPage();if(src==='channel')return channelPage();
const currency=f.currency||'USD',balance=a.balances[currency]||0;
return `${head('转入跨境宝',`从${a.name}转入，让资金集中管理。`,link(icon('back')+' 返回资金来源','transfer-back'))}${steps(['选择资金来源','填写转入信息','确认与结果'],C.stage===1?1:2)}<div class="form-layout"><section class="panel form-panel">${C.stage===1?`<div class="bankcard"><span class="source-icon ${src}">${src==='intl'?'a':'AP'}</span><div><b style="font-size:13px">${a.name} → 跨境宝</b><p>杭州远帆贸易有限公司 · 同主体账户</p></div>${tag(a.authorized?'已授权':'已关闭',a.authorized?'green':'orange')}</div>${!a.authorized?note('此资金来源尚未授权，授权后才可转入或用于采购。','warn'):''}${select('转入币种','currency',Object.keys(M.rates).map(c=>[c,c]),currency)}${amountField('转入金额','amount',f.amount,currency,`可转入 ${currency} ${fmt(balance)} · 冻结及待结算金额不计入`,true)}${kv('预计到账','转入完成后更新钱包余额')}${kv('转入费用',currency+' 0.00')}${error()}<div class="formfooter">${b('返回','transfer-back')}${b(a.authorized?'下一步':'去授权',a.authorized?'transfer-next':'auth-source','primary')}</div>`:`<h2 style="margin-bottom:25px">确认转入信息</h2>${kv('转出账户',a.name)}${kv('转入账户','跨境宝 · 同币种账户')}${kv('转入金额',currency+' '+fmt(f.amount))}${kv('转入费用',currency+' 0.00')}${kv('实际到账',currency+' '+fmt(f.amount),'total')}${note('转入后将相应减少'+a.name+'余额，并增加跨境宝余额。三方总资产不变。')}${error()}<div class="formfooter">${b('上一步','transfer-edit')}${b('确认转入','transfer-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>当前资金情况</h3>${kv(a.name+'可用',currency+' '+fmt(balance))}${kv('跨境宝可用',currency+' '+fmt(S.accounts.wallet.balances[currency]))}<div class="divider-line"></div><p>仅可转入已结算、可支配的资金。采购占用、冻结和未结算资金不会被重复使用。</p><p>收款是货款到账，实际利润需要结合采购、物流等成本另行核算。</p>${link('查看可采购额度','quota')}</aside></div>`;}
function transferOutPage(){const f=C.fields;if(C.stage===3)return resultPage();if(C.stage===0)return `${head('转出','将跨境宝余额转至你的其他资金账户。',b('转出记录','transferout-records'))}${steps(['选择转入账户','填写转出信息','确认与结果'],0)}<div class="form-layout"><section class="panel form-panel"><h2 style="margin-bottom:10px">资金转到哪里？</h2><p class="tiny muted" style="margin-bottom:24px">选择同一企业主体下的 ACP 或国际站账户。</p><div class="choice-grid">${[['acp','AP','ACP 账户','Alibaba Pay 收款账户'],['intl','a','国际站账户','阿里国际站资金账户']].map(([id,ic,t,sub])=>`<button class="choice" data-action="out-select" data-id="${id}"><span class="source-icon ${id}">${ic}</span><div><h3>${t}</h3><p>${sub}</p></div>${icon('chevron')}</button>`).join('')}</div>${note('转出完成后，跨境宝余额减少，目标账户同币种余额增加。资金在你的账户间划转。')}</section><aside class="panel side-info"><h3>转出和提现</h3><p>转出用于跨境宝与 ACP、国际站之间的资金调拨。</p><p>转至银行卡，请使用独立的「提现」入口。</p>${link('去提现 '+icon('arrow'),'go-withdraw')}</aside></div>`;const c=f.currency,a=S.accounts[f.destination],balance=S.accounts.wallet.balances[c];return `${head('转出至'+a.name,'仅从跨境宝可用余额转出，按原币种到账。',link(icon('back')+' 返回账户选择','out-back'))}${steps(['选择转入账户','填写转出信息','确认与结果'],C.stage===1?1:2)}<div class="form-layout"><section class="panel form-panel">${C.stage===1?`<div class="bankcard"><span class="source-icon ${f.destination}">${f.destination==='acp'?'AP':'a'}</span><div><b>跨境宝 → ${a.name}</b><p>杭州远帆贸易有限公司 · 同主体账户</p></div>${tag('账户已连接','green')}</div>${select('转出币种','currency',Object.keys(M.rates).map(c=>[c,c]),c)}${amountField('转出金额','amount',f.amount,c,`可转出 ${c} ${fmt(balance)} · 冻结资金不可转出`,true)}${kv('转出费用',c+' 0.00')}${kv('预计到账','转出完成后更新目标账户余额')}${error()}<div class="formfooter">${b('返回','out-back')}${b('下一步','out-next','primary')}</div>`:`<h2 style="margin-bottom:25px">确认转出信息</h2>${kv('转出账户','跨境宝')}${kv('转入账户',a.name+' · 同币种账户')}${kv('转出金额',c+' '+fmt(f.amount))}${kv('转出费用',c+' 0.00')}${kv('实际到账',c+' '+fmt(f.amount),'total')}${note('确认后将从跨境宝扣减对应币种资金，并记入'+a.name+'。')}${!a.authorized?note('该账户的余额调用授权已关闭。转入该账户的资金暂不计入可采购额度，可在支付管理中开启。','warn'):''}${error()}<div class="formfooter">${b('上一步','out-edit')}${b('确认转出','out-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>当前资金情况</h3>${kv('跨境宝可用',c+' '+fmt(balance))}${kv(a.name+'可用',c+' '+fmt(a.balances[c]))}<div class="divider-line"></div><p>转出仅校验跨境宝所选币种的可用余额，其他账户的余额不会用于补足。</p><p>本流程不自动汇兑。如需更换币种，可先在汇兑模块完成兑换。</p>${link('查看可采购额度构成','quota')}</aside></div>`;}
function bankTransferPage(){const f=C.fields;return `${head('银行转账转入','使用同名企业银行账户，汇入跨境宝。',link(icon('back')+' 返回资金来源','transfer-back'))}${steps(['选择资金来源','填写转入信息','确认与结果'],1)}<div class="form-layout"><section class="panel form-panel">${select('入账币种','currency',Object.keys(M.rates).map(c=>[c,c]),f.currency)}${amountField('计划转入金额','amount',f.amount,f.currency)}${note('以下收款信息仅用于原型演示，不可用于真实汇款。','warn')}<div class="receipt" style="margin:0;max-width:none">${kv('收款主体','杭州远帆贸易有限公司（演示）')}${kv('收款银行','演示银行 · 跨境收款专户')}${kv('收款账号','DEMO **** 8632')}${kv('汇款附言','DEMO-YF-20261108')}</div><p class="tiny muted" style="margin-top:17px">实际到账金额以银行入账为准。提交转入意向不会增加可用余额。</p>${error()}<div class="formfooter">${b('复制收款信息','copy-bank')}${b('我已汇款（演示）','bank-intent','primary')}</div></section><aside class="panel side-info"><h3>到账后才能使用</h3><p>完成银行汇款后，在转入详情中查看入账进度。待入账金额不会计入可采购额度。</p><p>若汇款主体或附言不一致，进入人工核对；修正后继续原交易，不重复入账。</p></aside></div>`;}
function channelPage(){const f=C.fields;return `${head('连接其他收款渠道','为更多外销渠道预留统一的收款入口。',link(icon('back')+' 返回资金来源','transfer-back'))}<div class="form-layout"><section class="panel form-panel">${select('渠道类型','channelType',[['market','其他电商平台'],['psp','第三方收款服务（PSP）'],['direct','线下贸易收款']],f.channelType||'market')}${field('渠道名称','channelName',f.channelName??'海外独立站','例如：独立站店铺或第三方收款服务，当前为连接流程演示。')}${field('渠道商户号','merchant',f.merchant??'DEMO-YF001','仅填写演示商户号，不填写密码或密钥。')}${select('新资金入账位置','channelRoute',[['wallet','转入跨境宝'],['source','留在渠道账户（需支持授权付款）']],f.channelRoute||'wallet')}${note('新增渠道需要先验证商户主体与收付款能力。未完成连接前，不纳入总资产和可采购额度。')}${error()}<div class="formfooter">${b('返回','transfer-back')}${b('确认连接（演示）','channel-connect','primary')}</div></section><aside class="panel side-info"><h3>可扩展的资金来源</h3><p>每个渠道独立保留收款币种、资金状态、原始流水和用途限制；钱包统一提供操作入口。</p><p>同一笔资金仅在实际所在的账户计入资产，渠道连接不会自动复制余额。</p></aside></div>`;}



function withdrawPage(){if(C.stage===3)return resultPage();const f=C.fields,c=f.currency||'CNY',banks=S.banks.filter(x=>x.currency===c),bank=banks.find(x=>x.id===f.bank)||banks[0],fee=c==='CNY'?2:c==='USD'?5:4,amt=num('amount'),available=S.accounts.wallet.balances[c];if(bank)f.bank=bank.id;return `${head('提现','将跨境宝可用余额，提至已验证的同名银行卡。',b('管理银行卡','banks'))}${steps(['填写提现信息','确认提现','到账结果'],C.stage===0?0:1)}<div class="form-layout"><section class="panel form-panel">${C.stage===0?`${select('提现币种','currency',Object.keys(M.rates).map(c=>[c,c]),c)}<div class="field"><div class="field-head"><span>到账银行卡</span>${link('+ 添加银行卡','add-bank')}</div>${banks.length?banks.map(x=>`<button class="bankcard ${f.bank===x.id?'selected':''}" style="width:100%;text-align:left" data-action="select-bank" data-id="${x.id}"><span class="bankicon">${icon('bank')}</span><span><b style="font-size:13px">${esc(x.name)} · ${x.tail}</b><p>杭州远帆贸易有限公司 · ${x.currency}</p></span>${tag(f.bank===x.id?'已选择':'同名账户',f.bank===x.id?'blue':'')}</button>`).join(''):note('还没有支持此币种的银行卡，请先添加。','warn')}</div>${amountField('提现到账金额','amount',f.amount,c,`可用 ${c} ${fmt(available)} · 另收 ${c} ${fmt(fee)} 提现费（示例）`,true)}${kv('预计扣除',c+' '+fmt((amt||0)+fee))}${kv('预计到账','1–2 个工作日（演示）')}${error()}<div class="formfooter">${b('下一步','withdraw-next','primary',!bank?'disabled':'')}</div>`:`<h2 style="margin-bottom:25px">确认提现信息</h2>${kv('提现账户','跨境宝 · '+c)}${kv('到账银行卡',esc(bank?.name)+' · '+esc(bank?.tail))}${kv('账户主体','杭州远帆贸易有限公司')}${kv('到账金额',c+' '+fmt(amt))}${kv('提现服务费',c+' '+fmt(fee))}${kv('合计扣除',c+' '+fmt(amt+fee),'total')}${note('提交后，提现金额和费用将暂时占用。银行处理成功后扣除；退回时释放占用，不重复扣款。')}${error()}<div class="formfooter">${b('上一步','withdraw-edit')}${b('确认提现','withdraw-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>哪些资金可以提现？</h3><p>此入口提现的是跨境宝可用余额。留在国际站或 ACP 的资金，可先按对应账户能力转入跨境宝。</p><p>不同币种分别核算。若希望人民币到账，可先将外币换汇，再发起人民币提现。</p>${link('去汇兑 '+icon('chevron'),'go-fx')}<div class="divider-line"></div>${kv('跨境宝 '+c+' 可用',fmt(available))}${kv('跨境宝 '+c+' 冻结',fmt(S.accounts.wallet.frozen[c]))}</aside></div>`;}
function fxCalc(){const f=C.fields,amount=num('amount')||0,fee=M.round(amount*.001),rate=M.rates[f.from]/M.rates[f.to];return {amount,fee,rate,received:M.round((amount-fee)*rate)};}
function fxPage(){if(C.stage===3)return resultPage();const f=C.fields,q=fxCalc(),wallet=S.accounts.wallet;return `${head('汇兑','在跨境宝账户内兑换币种，灵活安排多币种资金。',link('汇兑记录','fx-records'))}${steps(['填写兑换金额','确认报价','兑换结果'],C.stage===0?0:1)}<div class="form-layout"><section class="panel form-panel">${C.stage===0?`<div class="exchange-box">${select('卖出币种','from',Object.keys(M.rates).map(c=>[c,c]),f.from)}${amountField('卖出金额','amount',f.amount,f.from,`可用 ${f.from} ${fmt(wallet.balances[f.from])}`,true)}</div><button class="exchange-direction" data-action="swap-fx" aria-label="交换买入和卖出币种">${icon('exchange')}</button><div class="exchange-box receive">${select('买入币种','to',Object.keys(M.rates).map(c=>[c,c]),f.to)}<div class="tiny muted">预计收到</div><div class="mono" style="font-size:28px;margin:8px 0" id="fx-received">${fmt(q.received)} <small style="font-size:14px;color:#7790b0">${f.to}</small></div></div><div class="quote-strip"><span>演示汇率 · 1 ${f.from} = ${fmt(q.rate,4)} ${f.to}</span>${tag('参考价','blue')}</div>${kv('汇兑服务费（示例 0.1%）',`<span id="fx-fee">${f.from} ${fmt(q.fee)}</span>`)}${note('费用从卖出金额内扣除。确认页会展示锁定报价和有效时间。')}${error()}<div class="formfooter">${b('获取报价','fx-next','primary')}</div>`:`<h2 style="margin-bottom:24px">确认兑换报价</h2><div class="quote-strip"><span>1 ${f.from} = ${fmt(q.rate,4)} ${f.to}</span><span id="quote-timer" class="${C.expired?'orange':'green'}">${C.expired?'报价已过期':'报价有效 '+Math.max(0,Math.ceil((C.expires-Date.now())/1000))+' 秒'}</span></div>${kv('卖出金额',f.from+' '+fmt(q.amount))}${kv('汇兑服务费',f.from+' '+fmt(q.fee))}${kv('实际参与兑换',f.from+' '+fmt(q.amount-q.fee))}${kv('实际收到',f.to+' '+fmt(q.received),'total')}${C.expired?note('当前报价已失效。重新获取报价后，需再次确认新金额。','warn'):note('确认后将从跨境宝扣除卖出金额，买入币种直接记入同一钱包。')}${error()}<div class="formfooter">${b('上一步','fx-edit')}${C.expired?b('重新获取报价','fx-refresh','primary'):b('确认兑换','fx-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>我的币种余额</h3>${Object.keys(M.rates).map(c=>kv(c,fmt(wallet.balances[c]))).join('')}<div class="divider-line"></div><p>此处兑换只调整跨境宝内的币种，不会改变国际站与 ACP 的币种余额。</p><p>采购时如需使用其他账户的外币，将在付款确认页展示对应汇兑方案，由你确认。</p>${link('设置付款时自动汇兑','go-settings')}</aside></div>`;}
function toggle(key,on){return `<button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${{fx:'付款时自动汇兑',card:'银行卡补款',coupon:'优先使用权益',auto:'自动采购付款'}[key]||key}" data-action="setting-toggle" data-key="${key}"></button>`;}
function settingRow(title,description,action){return `<div class="setting-row"><div class="content"><h3>${title}</h3><p>${description}</p></div>${action}</div>`;}
function settingsPage(){const d=C.draft,auth=C.authDraft,quota=M.round(d.order.reduce((sum,id)=>sum+(auth[id]?M.equivalent(S.accounts[id].balances):0),0));return `${head('支付管理','统一管理支付顺序、资金来源授权和已绑定的 1688 账号。',link(icon('back')+' 返回钱包','go-home'))}<div class="management-layout"><section class="panel management-panel"><div class="sectionhead"><div><h2>支付顺序与授权</h2><p class="tiny muted" style="margin-top:8px">从上到下依次使用余额；关闭的渠道会自动跳过。</p></div>${tag('余额优先','blue')}</div><div class="management-list">${d.order.map((id,i)=>{const a=S.accounts[id],on=auth[id];return `<div class="management-row ${on?'':'disabled-source'}" draggable="true" data-source="${id}"><span class="drag-handle" aria-hidden="true">⠿</span><span class="order-index">${i+1}</span><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span><div class="management-source"><h3>${a.name}${id==='acp'?'<small>Alibaba Pay</small>':''}</h3><p>可用余额 ${money(M.equivalent(a.balances))}</p></div><div class="reorder-buttons">${b(icon('sortup'),'move-source','icon-only',`data-index="${i}" data-dir="-1" aria-label="上移${a.name}" ${i===0?'disabled':''}`)}${b(icon('sortdown'),'move-source','icon-only',`data-index="${i}" data-dir="1" aria-label="下移${a.name}" ${i===d.order.length-1?'disabled':''}`)}</div><div class="authorization-control"><button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${a.name}余额调用授权" data-action="authorization-toggle" data-id="${id}" ${id==='wallet'?'disabled':''}></button><span>${id==='wallet'?'默认启用':on?'已授权':'已关闭'}</span></div></div>`;}).join('')}</div><p class="tiny muted" style="margin:16px 0 25px">拖动整行或使用上下箭头排序。跨境宝为钱包自有余额，默认启用。</p>${note('国际站与 ACP 的余额调用授权已默认开启。关闭后，该账户将不参与新交易扣款与转入，余额也不计入可采购额度；资金仍留在原账户，已提交交易继续处理。')}${error()}<div class="formfooter">${b('恢复已保存设置','settings-cancel')}${b('保存更改','settings-save','primary')}</div></section><aside class="panel side-info management-preview"><h3>生效预览</h3><p>保存后，将按以下顺序使用已授权余额。</p><div class="payment-order-preview">${d.order.filter(id=>auth[id]).map((id,i)=>`<div><span>${i+1}</span><b>${S.accounts[id].name}</b></div>`).join('')}</div><div class="divider-line"></div>${kv('保存后可采购额度',money(quota),'total')}<p>开启授权不会将资金自动转入跨境宝。关闭授权也不会转走账户内的资金。</p><p>本页管理余额调用权限；银行卡在提现流程中选择。</p><div class="divider-line"></div><div class="binding-overview"><span class="binding-logo">1688</span><div><b>采购账号授权</b><p>已授权 ${S.linked1688.filter(x=>x.status==='authorized').length} 个账号</p></div></div>${link('管理已绑定账号 '+icon('arrow'),'binding-scroll')}</aside></div>${boundAccountsPanel()}`;}
function boundAccountsPanel(){const rows=S.linked1688,active=rows.filter(x=>x.status==='authorized').length;return `<section class="panel linked-accounts-panel" id="linked-accounts"><div class="linked-accounts-head"><div class="linked-accounts-title"><span class="binding-logo">1688</span><div><h2>1688 账号管理 <span class="tag blue">已授权 ${active} 个账号</span></h2><p>管理哪些采购账号可以在 1688 收银台使用这个钱包付款。</p></div></div>${b(icon('plus')+' 授权更多账号','binding-add','primary')}</div>${rows.length?`<div class="table-wrap"><table class="binding-table"><thead><tr><th>已绑定账号</th><th>适用场景</th><th>最近授权时间</th><th>授权状态</th><th>操作</th></tr></thead><tbody>${rows.map(row=>`<tr><td><div class="title">${esc(row.label)}</div><div class="sub">${esc(row.account)}</div></td><td><span>1688 采购付款</span><div class="sub">${esc(row.owner)}</div></td><td class="mono">${esc(row.authorizedAt)}</td><td>${tag(row.status==='authorized'?'已授权':'已解除',row.status==='authorized'?'green':'')}</td><td><div class="binding-row-actions">${link('查看授权','binding-detail',`data-id="${esc(row.id)}"`)}${row.status==='authorized'?b('解除授权','binding-revoke','binding-link-danger',`data-id="${esc(row.id)}"`):link('重新授权','binding-reauthorize',`data-id="${esc(row.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="binding-empty">${icon('link')}<h3>暂未绑定 1688 账号</h3><p>授权采购账号后，即可在其 1688 收银台使用跨境宝。</p>${b('授权第一个账号','binding-add','primary')}</div>`}<div class="binding-footer-note">${icon('info')}<span>账号授权确认后立即生效；多个账号共用当前钱包及支付顺序，不增加账户余额或可采购额度。每笔付款仍需按交易规则确认。</span></div></section>`;}
let bindingDraft=null;
function bindingForm(values={}){bindingDraft={account:values.account||'',label:values.label||'',owner:'杭州远帆贸易有限公司'};modalState={kind:'binding-form'};modal('授权新的 1688 账号',`<div class="binding-modal-brand"><span class="binding-logo">1688</span><div><h3>连接采购账号</h3><p>步骤 1 / 2 · 选择待授权账号</p></div></div>${field('1688 账号（演示）','binding-account',bindingDraft.account,'原型模拟账号识别，无需输入密码或验证码。','maxlength="40" autocomplete="off" placeholder="例如：yuanfan_purchase_02"')}${field('备注名称（选填）','binding-label',bindingDraft.label,'用于区分不同采购账号，最多 24 个字。','maxlength="24" placeholder="例如：日用品采购账号"')}${note('下一步将核对账号主体和授权范围。本原型不会连接真实 1688 账号。')}<div class="error-text" id="binding-error" role="alert"></div>`,b('取消','close-modal')+b('下一步，核对授权','binding-next','primary'));}
function bindingReview(input){bindingDraft={account:input.account,label:input.label,owner:input.owner};modalState={kind:'binding-review'};modal('确认 1688 账号授权',`<div class="binding-modal-brand"><span class="binding-logo">1688</span><div><h3>核对账号与授权范围</h3><p>步骤 2 / 2 · 确认后加入已授权账号</p></div></div>${kv('1688 账号',esc(input.account))}${kv('备注名称',esc(input.label))}${kv('账号主体',esc(input.owner))}${kv('主体校验',tag('同一企业主体 · 演示','green'))}<div class="binding-scope"><h3>本次授权允许</h3><ul><li>读取账号基础信息，建立钱包绑定关系</li><li>关联该账号的采购订单及资金流水</li><li>在该账号的 1688 收银台使用跨境宝付款，沿用当前支付顺序</li></ul></div>${note('绑定账号不会自动发起采购或扣款，不会增加钱包余额；可随时在本页解除授权。')}<label class="checkrow"><input id="binding-consent" type="checkbox"><span>我已确认上述账号及授权范围，同意将其绑定至当前钱包。</span></label><div class="error-text" id="binding-error" role="alert"></div>`,b('上一步','binding-back')+b('模拟确认授权','binding-confirm','primary'));}
function bindingDetail(id){const row=S.linked1688.find(x=>x.id===id);if(!row)return;modalState={kind:'binding-detail',id};modal('1688 账号授权详情',`${kv('1688 账号',esc(row.account))}${kv('备注名称',esc(row.label))}${kv('账号主体',esc(row.owner))}${kv('授权状态',tag(row.status==='authorized'?'已授权':'已解除',row.status==='authorized'?'green':''))}${kv('最近授权时间',esc(row.authorizedAt))}${row.revokedAt?kv('解除时间',esc(row.revokedAt)):''}<div class="binding-scope"><h3>授权范围</h3><ul><li>账号基础信息与钱包绑定关系</li><li>采购订单关联及资金流水查询</li><li>通过 1688 收银台使用当前钱包付款</li></ul></div>${note(row.status==='authorized'?'该账号沿用当前钱包的支付顺序与资金来源授权，每笔付款仍需按交易规则确认。':'该账号已无法通过此钱包发起新的采购付款，历史订单与资金明细保留。')}`,b('关闭','close-modal')+(row.status==='authorized'?b('解除授权','binding-revoke','binding-danger',`data-id="${esc(id)}"`):b('重新授权','binding-reauthorize','primary',`data-id="${esc(id)}"`)),true);}
function bindingRevoke(id){const row=S.linked1688.find(x=>x.id===id);if(!row||row.status!=='authorized')return;modalState={kind:'binding-revoke',id};modal('解除 1688 账号授权',`${kv('1688 账号',esc(row.account))}${kv('备注名称',esc(row.label))}${note('解除后，这个账号不能再通过当前钱包发起新的 1688 采购付款。已提交交易继续处理，历史资金明细保留。','warn')}<p class="tiny muted" style="line-height:1.9;margin-top:16px">钱包余额、可采购额度与其他账号不受影响。之后可以重新授权此账号。</p><div class="error-text" id="binding-error" role="alert"></div>`,b('暂不解除','close-modal')+b('确认解除授权','binding-revoke-confirm','binding-danger',`data-id="${esc(id)}"`));}
function bindingAction(action,el){if(!action.startsWith('binding-'))return false;if(action==='binding-scroll'){document.getElementById('linked-accounts')?.scrollIntoView({behavior:'smooth',block:'start'});return true;}if(action==='binding-add'){bindingForm();return true;}if(action==='binding-detail'){bindingDetail(el.dataset.id);return true;}if(action==='binding-revoke'){bindingRevoke(el.dataset.id);return true;}if(action==='binding-back'){bindingForm(bindingDraft||{});return true;}try{if(action==='binding-next'){const d=M.validate1688(S,$('#binding-account').value,$('#binding-label').value);bindingReview(d);}else if(action==='binding-reauthorize'){const row=S.linked1688.find(x=>x.id===el.dataset.id);if(!row)throw Error('账号不存在，请刷新后重试。');bindingReview(M.validate1688(S,row.account,row.label,row.owner));}else if(action==='binding-confirm'){if(modalState?.kind!=='binding-review'||!bindingDraft)return true;const row=M.authorize1688(S,bindingDraft,$('#binding-consent')?.checked===true);persist();closeModal();bindingDraft=null;render();document.getElementById('linked-accounts')?.scrollIntoView({block:'start'});modal('1688 账号授权成功',`<div class="binding-success">${icon('check')}<h3>已绑定，可用于采购付款</h3><p>${esc(row.label)} · ${esc(row.account)}</p></div>${note('该账号已加入下方列表，可查看授权详情或解除授权。账户余额与可采购额度未发生变化。','success')}`,b('完成，查看账号','close-modal','primary'));}else if(action==='binding-revoke-confirm'){if(modalState?.kind!=='binding-revoke'||modalState.id!==el.dataset.id)return true;M.revoke1688(S,el.dataset.id);persist();closeModal();render();document.getElementById('linked-accounts')?.scrollIntoView({block:'start'});toast('该 1688 账号授权已解除，其他账号不受影响');}}catch(err){const target=$('#binding-error');if(target)target.textContent=err.message;else toast(err.message);}return true;}
function filteredTx(){const f=C.fields;return S.tx.filter(t=>(!f.type||f.type==='all'||t.type===f.type)&&(!f.status||f.status==='all'||t.status===f.status)&&(!f.search||[t.title,t.id,t.detail].join(' ').includes(f.search)));}
function recordsPage(){const rows=filteredTx();return `${head('资金明细','转入、转出、提现、汇兑，每笔资金都能追溯。',b(icon('download')+' 导出当前明细','export'))}<section class="panel"><div class="toolbar"><select name="type" aria-label="交易类型"><option value="all">全部交易类型</option>${['收款','转入','转出','付款','提现','汇兑'].map(x=>`<option ${C.fields.type===x?'selected':''}>${x}</option>`).join('')}</select><select name="status" aria-label="交易状态"><option value="all">全部交易状态</option>${['已完成','处理中','待入账','已退回','付款失败'].map(x=>`<option ${C.fields.status===x?'selected':''}>${x}</option>`).join('')}</select><input name="search" aria-label="搜索流水" placeholder="搜索交易名称、订单号或流水号" value="${esc(C.fields.search||'')}">${b(icon('search')+' 查询','records-search','primary small')}${b('重置','records-reset','small')}</div><div class="sectionhead" style="margin:0"><span class="tiny muted">2026-11-08 · 共 ${rows.length} 笔记录</span><span class="tiny muted">账户间转入不重复计为外部收入</span></div></section><section class="panel flush">${txTable(rows)}</section>${note('点击详情可查看原始收款渠道、外销单、采购单、各账户扣款与处理状态。跨币种交易保留原币金额。')}`;}
function benefitsPage(){return `${head('权益中心','把每一笔费用看清楚，让优惠用在适合的交易上。',link('返回钱包','go-home'))}${note('以下费率与权益为交互设计示例，不代表正式商户报价或服务承诺。')}<div class="benefit-grid"><section class="coupon">${tag('已生效 · 示例','blue')}<h3 style="margin-top:18px">采购支付服务费</h3><div class="coupon-value">0.125<span style="font-size:15px">%</span></div><p>适用演示采购付款，付款确认页展示本次费用。</p>${b('查看计算方式','fee-info','small')}</section><section class="coupon">${tag('已生效 · 示例','blue')}<h3 style="margin-top:18px">账户内币种兑换</h3><div class="coupon-value">0.10<span style="font-size:15px">%</span></div><p>从卖出金额中扣除，获取报价后再确认。</p>${b('去汇兑','go-fx','small')}</section><section class="coupon">${tag('企业服务','green')}<h3 style="margin-top:18px">统一资金账单</h3><div class="coupon-value">免费</div><p>收付流水、跨账户资金调拨统一查询与导出。</p>${b('查看资金明细','go-records','small')}</section></div><section class="panel" style="margin-top:23px"><h2>费用减免券</h2><div class="empty" style="padding:34px">当前暂无可用减免券<div class="tiny" style="margin-top:8px">如有符合条件的权益，将在付款前自动匹配并展示。</div></div></section>`;}
function helpPage(){return `${head('帮助中心','关于跨境宝，你可能想了解这些。')}<section class="panel form-panel help-list">${[['账户余额和可采购额度有什么不同？','账户余额是跨境宝自身的可用与冻结资金。可采购额度合计跨境宝、ACP、国际站已授权的可用余额，点击额度旁的小 i 可查看构成。'],['转出和提现有什么区别？','转出将跨境宝资金转至同主体 ACP 或国际站账户；提现将资金提至同名企业银行卡。'],['在哪里管理渠道授权？','从首页资金模块右上角进入支付管理，可在同一页调整支付顺序、开启或关闭 ACP 与国际站余额调用授权，保存后生效。'],['授权开关关闭后，钱会被转走吗？','不会。资金仍留在原账户，但不参与新的余额调用，也不计入可采购额度。'],['可以直接使用其他币种吗？','转入和转出保持原币种；币种转换通过汇兑模块操作，确认有效报价后执行。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`;}
function resultPage(){const t=C.record;if(!t)return home();const pending=['处理中','待入账'].includes(t.status),fail=['已退回','付款失败'].includes(t.status);const title=t.type==='提现'?(pending?'提现申请已提交':fail?'提现已退回':'提现已到账'):t.type==='付款'?(pending?'付款处理中':fail?'付款未完成':'付款成功'):t.type==='汇兑'?'兑换成功':t.status==='待入账'?'等待银行入账':t.type==='转入'?'转入成功':t.type==='转出'?'转出成功':'收款到账';return `${head(t.type+'结果','随时可在资金明细中追踪这笔交易。')}<section class="panel form-panel"><div class="result"><div class="result-icon ${pending?'pending':fail?'fail':''}">${icon(pending?'clock':fail?'close':'check')}</div><h2>${title}</h2><p>${esc(t.note||'账户余额与资金明细已同步更新。')}</p><div class="big mono">${esc(t.display)}</div><div class="receipt">${kv('交易流水号',t.id)}${kv('业务类型',t.title)}${kv('交易状态',tag(t.status,pending?'orange':fail?'red':'green'))}${t.bank?kv('到账银行卡',esc(t.bank)):''}${t.fee!==undefined?kv('服务费',t.currency+' '+fmt(t.fee)):''}${t.type==='付款'?kv('关联订单',esc(t.order||'202611080126')):''}${kv('提交时间',t.time)}${t.destination?kv('转入账户',S.accounts[t.destination].name):''}</div><div class="result-actions">${pending?b(t.type==='转入'?'刷新入账状态（演示）':'查询处理结果（演示）','resolve-tx','primary','data-outcome="success"'):b('返回钱包','go-home','primary')}${b('查看交易详情','tx','',`data-id="${t.id}"`)}${pending?b(t.type==='提现'?'模拟银行退回':'模拟处理失败','resolve-tx','',`data-outcome="fail"`):b('再办一笔','again')}</div>${t.type==='付款'&&t.status==='已完成'?'<div class="finish-note">采购单已更新为「已付款」，关联外销订单保留。可在交易详情追溯三方资金扣款。</div>':''}${pending?'<div class="finish-note">处理中仅查询原交易，不生成新的扣款申请。预留金额暂不可用于其他付款。</div>':''}</div></section>`;}
const FLOWS={
transfer:{name:'转入',title:'多渠道资金转入跨境宝',intro:'选择来源，填写币种和金额，确认并核验后查看结果。',steps:[['R01','选择来源','转入','国际站 / ACP / 银行 / 其他','首页资金模块点击转入。'],['R02','填写金额','从国际站转入','USD 1,000.00','只使用已授权、已结算的可用资金。'],['R03','确认信息','转入跨境宝','实际到账 USD 1,000.00','展示来源、费用和到账金额，确认后核验权限。'],['R04','查看结果','转入成功','+ USD 1,000.00','原账户减少、跨境宝增加；查看交易明细。']],branches:[['unauth','来源授权关闭','进入支付管理开启授权，保存后重新选择来源。'],['bankpending','银行来款待入账','保留转入意向，到账后才增加可用额度。'],['pendingfunds','资金待结算','查看结算进度，不提前计入可用资金。']]},
transferout:{name:'转出',title:'从跨境宝转至 ACP 或国际站',intro:'转出是同主体账户间划转；转至银行卡使用独立的提现模块。',steps:[['O01','选择账户','转出','ACP / 国际站','首页点击转出，再选择资金转入账户。'],['O02','填写金额','跨境宝 → ACP','USD 1,000.00','选择原币种，校验跨境宝可用余额。'],['O03','确认转出','转出至 ACP','实际到账 USD 1,000.00','核对账户、金额和费用，确认后核验权限。'],['O04','查看结果','转出成功','− USD 1,000.00','钱包减少、目标账户增加，明细可追溯。']],branches:[['outshort','跨境宝余额不足','拦截并保留输入，可减少金额或先转入。'],['outintl','转至国际站','选择国际站后，使用相同的转出确认流程。'],['outdisabled','目标授权关闭','仍可转入该账户；到账资金不计入可采购额度。']]},
withdraw:{name:'提现',title:'从钱包到同名企业银行卡',intro:'选择币种与银行卡，校验金额和费用，提交后追踪银行结果。',steps:[['W01','选择账户','提现至银行卡','招商银行 · 6288','首页点击提现，选择同币种企业银行卡。'],['W02','填写金额','提现到账金额','CNY 5,000.00','可用余额须覆盖金额和费用。'],['W03','确认申请','确认提现','合计扣除 CNY 5,002.00','核验权限后占用资金，等待银行处理。'],['W04','追踪结果','提现处理中','预计 1–2 个工作日','成功扣款，退回则释放占用。']],branches:[['withdrawshort','余额不足','按钱包对应币种余额校验。'],['nobank','没有同币种银行卡','添加并验证企业银行卡。'],['bankreturn','银行退回','查看原因，释放余额后重新发起。']]},
fx:{name:'汇兑',title:'确认有效报价后进行币种兑换',intro:'在跨境宝账户内兑换，卖出金额、费用和实际买入金额分别展示。',steps:[['F01','选择币种','美元兑换人民币','USD → CNY','选择卖出与买入币种。'],['F02','填写金额','卖出金额','USD 1,000.00','查看参考汇率与费用。'],['F03','确认报价','报价有效 30 秒','收到 CNY 7,092.90','确认有效报价并核验权限。'],['F04','查看结果','兑换成功','+ CNY 7,092.90','两个币种的余额与交易明细同步。']],branches:[['quoteexpired','报价过期','重新报价并再次确认。'],['fxshort','卖出余额不足','减少卖出金额或先转入。'],['samecurrency','买卖币种相同','提示选择不同币种。']]},
settings:{name:'支付管理',title:'同一页管理支付顺序与渠道授权',intro:'首页资金模块右上角进入。三个账户默认启用；调整顺序或开关后统一保存生效。',steps:[['S01','进入管理','支付管理','支付顺序 + 授权开关','无需切换子页或标签。'],['S02','调整顺序','拖动或上下移动','跨境宝 → ACP → 国际站','整行排序，已关闭渠道会被跳过。'],['S03','调整授权','ACP / 国际站开关','保存后可采购额度同步变化','关闭仅停止新余额调用，不转走原账户资金。'],['S04','保存更改','规则已保存','对新交易生效','可恢复已保存设置或返回钱包查看额度。']],branches:[['settings-off','关闭国际站授权','同页显示关闭状态与额度预览。'],['settings-order','调整默认顺序','上下移动渠道并预览顺序。'],['binding-manage','管理已绑定的 1688 账号','查看授权详情、解除授权，或新增更多采购账号。']]}
};
function miniFrame(flow,step,i){const [code,label,title,value,caption]=step;return `<div class="frame-wrap"><div class="frame-label"><span>${code} / ${label}</span><span>PC</span></div><div class="frame" role="button" tabindex="0" data-action="flow-jump" data-flow="${flow}" data-step="${i}" aria-label="体验${label}"><div class="mini-top"><i></i><i></i><i></i><span>阿里国际站 · 跨境宝</span></div><div class="mini-body"><h4>${title}</h4>${i===3?`<div class="mini-result"><b>✓</b><div class="mini-value" style="font-size:13px">${value}</div></div><div class="mini-field">账户余额与交易明细同步</div><div class="mini-button">查看结果 / 体验此步</div>`:`<div class="mini-label">${i===0?'操作入口':i===1?'输入与选择':'确认信息'}</div><div class="mini-card">${value}</div><div class="mini-field">${flow==='pay'?'跨境宝余额 · 优先扣款':flow==='withdraw'?'企业同名账户 · 已验证':flow==='fx'?'服务费与实际到账金额':'账户信息与资金状态'}</div><div class="mini-field">${flow==='pay'?'其他资金来源 · 顺序补足':'可用余额 · 实时校验'}</div><div class="mini-button">${i===0?'进入流程':i===1?'下一步':'确认并继续'} →</div>`}</div></div><div class="frame-caption">${caption}</div></div>`;}
function flowPage(){const flow=FLOWS[C.flow]||FLOWS.transfer;return `<div class="flowpage">${head('用户动线','像翻阅设计稿一样看完整流程，也可以点击画面直接体验。',tag('4 条资金动线 + 支付管理','blue'))}<div class="flowtabs">${Object.entries(FLOWS).map(([id,f])=>`<button class="${C.flow===id?'active':''}" data-flowtab="${id}">${f.name}</button>`).join('')}</div><div class="flowintro"><h2>${flow.title}</h2><p>${flow.intro}</p></div><div class="frames">${flow.steps.map((s,i)=>miniFrame(C.flow,s,i)).join('')}</div><div class="sectionhead"><h2>在这些情况下，流程如何分支？</h2><span class="tiny muted">点击卡片进入对应状态</span></div><div class="branch-grid">${flow.branches.map(([id,title,text])=>`<button class="branch" data-scenario="${id}"><h4>${title} ${icon('arrow')}</h4><p>${text}</p></button>`).join('')}</div><div class="panel side-info"><h3>评审时可以这样走一遍</h3><p style="margin:0">先看正常路径里的信息是否足够决策，再点击异常分支，看提示能否帮助商家继续操作。右下角「情景演示」可随时切换状态；「重置」恢复初始账户金额与设置。此视图中的结果卡可直接预览，不会改动余额。</p></div></div>`;}
function specPage(){return `${head('设计说明','四个资金操作入口，共享一个清晰的账户总览。',tag('V1.2 · 评审稿','blue'))}<div class="spec-grid"><article class="spec-card"><h3>01 / 首页信息层级</h3><p>账户余额、我的费率、可采购额度并排展示在同一深色模块，转入、转出、提现、汇兑位于模块底部。转入作为主要行动突出显示。</p><p>可采购额度旁的小 i 打开额度构成抽屉；支付管理位于资金模块右上角。</p></article><article class="spec-card"><h3>02 / 资金口径</h3><div class="formula">账户余额 = 跨境宝可用余额 + 冻结余额<br>可采购额度 = 三方已授权可用余额折算合计</div><p>内部转入转出不增加三方总资产。冻结、待结算和银行卡余额不计入额度；真实采购仍需按币种、用途、费用和限额校验。</p></article><article class="spec-card"><h3>03 / 转出与提现</h3><p>转出从跨境宝划转至同主体 ACP 或国际站账户，按原币种转出，不跨账户拼凑余额。</p><p>提现独立处理银行卡选择、费用、资金占用和银行返回结果。付款执行在采购业务收银台承接，本钱包不再提供独立付款模块。</p></article><article class="spec-card"><h3>04 / 支付管理</h3><p>单页呈现账户排序、资金来源授权与 1688 账号管理。跨境宝默认启用，ACP 与国际站授权可开关；关闭渠道自动跳过，不影响原账户资金。</p><p>1688 账号管理支持查看已绑定账号、新增授权、解除与重新授权。多个采购账号共用钱包，不扩大额度；账号授权确认后立即生效。</p><p>修改后统一保存，影响下一笔新交易与可采购额度。关闭授权的账户仍可作为转出收款方，到账后暂不计入可采购额度。</p></article></div><section class="panel flush" style="margin-top:23px"><div class="panel-title"><h2>页面与跳转</h2><a class="textbtn" href="wireflow.html" target="_blank" rel="noopener">打开完整用户动线图 ↗</a></div><table class="spec-table"><thead><tr><th>入口</th><th>主流程</th><th>异常出口</th></tr></thead><tbody>${[['转入','选择来源 → 币种与金额 → 确认 → 核验 → 结果','未授权进入支付管理；银行来款等待入账'],['转出','选择 ACP / 国际站 → 币种与金额 → 确认 → 核验 → 结果','余额不足保留输入，减少金额或先转入'],['提现','币种与银行卡 → 金额与费用 → 核验 → 查询结果','缺卡添加；银行退回释放占用'],['汇兑','币种与金额 → 有效报价 → 核验 → 结果','余额不足拦截；报价过期重新获取'],['支付管理','调整顺序 / 授权开关 → 预览 → 保存','恢复已保存设置；回到钱包查看额度'],['1688 账号管理','账号列表 → 新增账号 → 核对授权 → 确认 → 结果','重复账号拦截；解除授权后二次确认；支持重新授权']].map(row=>`<tr>${row.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></section><div class="design-note">原型使用演示数据。跨产品划转能力、费用、汇率和到账时效为评审假设，未接入真实资金系统。</div>`;}
let returnFocus=null;
function modal(title,body,footer='',drawer=false){returnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-bg ${drawer?'drawer-bg':''}"><section class="modal ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="iconbtn" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;$('#overlay button')?.focus();}
function closeModal(){const old=returnFocus;$('#overlay').innerHTML='';modalState=null;if(old?.isConnected)old.focus();}
function accountDrawer(id){if(id==='all'){quotaDrawer();return;}const a=S.accounts[id];modalState={kind:'account',id};modal(a.name+'账户',`<div class="account-top"><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span>杭州远帆贸易有限公司 ${tag(id==='wallet'?'默认启用':a.authorized?'已授权':'已关闭',a.authorized?'green':'orange')}</div>${kv('账户可用余额（折合 CNY）',money(M.equivalent(a.balances)),'total')}<div class="divider-line"></div><h3 style="font-size:13px">按币种查看</h3>${Object.keys(M.rates).map(c=>`<div class="setting-row"><div class="content"><h3>${c}</h3><p>冻结 / 待结算 ${fmt(a.frozen[c])}</p></div><b class="mono">${fmt(a.balances[c])}</b></div>`).join('')}${note(id==='wallet'?'跨境宝余额可用于转出、提现、汇兑及采购。':'资金仍在'+a.name+'账户。余额调用授权统一在支付管理中调整，授权不会自动划转资金。')}`,b('查看相关明细','account-records','',`data-id="${id}"`)+(id==='wallet'?'':b('支付管理','go-settings'))+b('完成','close-modal','primary'),true);}
function quotaDrawer(){const frozen=M.round(Object.values(S.accounts).reduce((sum,a)=>sum+M.equivalent(a.frozen),0));modal('可采购额度构成',`<div class="tiny muted">可采购额度 · 折合 CNY</div><div class="account-value mono">${money(M.available(S))}</div><p class="tiny muted">三个资金账户已授权、可支配余额的合计</p><div class="divider-line"></div>${['wallet','acp','intl'].map(id=>`<div class="quota-source">${kv(S.accounts[id].name,money(S.accounts[id].authorized?M.equivalent(S.accounts[id].balances):0))}<div class="tiny muted">${S.accounts[id].authorized?Object.entries(S.accounts[id].balances).filter(([c,n])=>n).map(([c,n])=>c+' '+fmt(n)).join(' + '):'授权已关闭 · 当前不计入额度'}</div></div>`).join('')}${kv('可采购额度合计',money(M.available(S)),'total')}${note('这是已有资金的可用额度，不是信用额度。未授权、冻结、待结算资金及银行卡余额不计入。')}${kv('冻结 / 待结算（不计入）',money(frozen))}<div class="divider-line"></div>${kv('演示折算汇率','USD 1 = CNY 7.1000<br>EUR 1 = CNY 8.0000')}<p class="tiny muted" style="line-height:1.9;margin-top:18px">实际采购前还需校验币种、用途、费用与限额。账户间划转只改变资金位置，不重复计算。</p>`,b('支付管理','go-settings')+b('知道了','close-modal','primary'),true);}
function txDrawer(id){const t=S.tx.find(t=>t.id===id)||(C.record?.id===id?C.record:null);if(!t)return;modalState={kind:'transaction',id};const pending=['处理中','待入账'].includes(t.status);modal('交易详情',`<div class="sectionhead"><h3>${esc(t.title)}</h3>${tag(t.status,pending?'orange':['付款失败','已退回'].includes(t.status)?'red':'green')}</div><div class="account-value mono" style="font-size:27px;margin:23px 0">${esc(t.display)}</div>${kv('交易流水号',t.id)}${kv('时间',t.time)}${kv('资金账户',S.accounts[t.source]?.name||'银行转入')}${kv('业务说明',esc(t.detail||''))}${t.destination?kv('转入账户',S.accounts[t.destination].name):''}${t.order?kv('采购订单',esc(t.order)):''}${t.bank?kv('银行卡',esc(t.bank)):''}${t.native?kv('原币金额',t.currency+' '+fmt(t.native)):''}${t.received?kv('买入金额',t.to+' '+fmt(t.received)):''}${t.fee!==undefined?kv('服务费',t.currency+' '+fmt(t.fee)):''}${t.q?`<div class="divider-line"></div><h3 style="font-size:13px">账户扣款明细</h3>${t.q.allocations.map(a=>`<div class="plan-row"><div class="plan-name">${S.accounts[a.id].name}<p>${a.parts.map(p=>p.currency+' '+fmt(p.native)+(p.change?'（兑换余款 CNY '+fmt(p.change)+' 留存）':'')).join(' + ')}</p></div><div class="mono">${money(a.value)}</div></div>`).join('')}${t.q.cardAmount?kv('银行卡补款',money(t.q.cardAmount)):''}`:''}<div style="margin-top:20px">${note(esc(t.note||'本笔交易可追溯至关联订单与资金账户。'),pending?'warn':'')}</div><div class="timeline"><div class="timeline-item">申请已提交<p>${t.time}</p></div><div class="timeline-item">${pending?'渠道正在处理':t.status==='已退回'?'银行退回，资金已释放':t.status==='付款失败'?'未完成，余额未扣除':'处理完成'}<p>${pending?'请查询此原始交易状态':'余额与资金明细已更新'}</p></div></div>`,pending?b('查看处理结果','show-tx-result','primary',`data-id="${t.id}"`):b('关闭','close-modal','primary'),true);}
function bankModal(){modal('我的企业银行卡',`${S.banks.map(x=>`<div class="bankcard"><span class="bankicon">${icon('bank')}</span><div><b>${esc(x.name)} · ${x.tail}</b><p>${x.currency} · 同名企业账户</p></div>${tag('已验证','green')}</div>`).join('')}${note('提现币种需与银行卡币种一致。只展示银行名称和尾号，不展示完整卡号。')}`,b('+ 添加银行卡','add-bank','primary'));}
function addBankModal(){modalState={kind:'add-bank'};modal('添加同名企业银行卡',`${field('账户主体','bank-holder','杭州远帆贸易有限公司','','readonly')}${field('银行名称','bank-name','招商银行')}${select('账户币种','bank-currency',Object.keys(M.rates).map(c=>[c,c]),C.page==='withdraw'?C.fields.currency:'CNY')}${field('银行卡尾号（演示）','bank-tail','','仅输入 4 位演示尾号，无需真实卡号。','inputmode="numeric" maxlength="4"')}${note('正式流程需要验证企业主体与银行卡归属。本原型仅模拟验证结果。')}<div class="error-text" id="modal-error"></div>`,b('取消','close-modal')+b('验证并添加（演示）','bank-add-confirm','primary'));}
function verify(kind){modalState={kind:'verify',transaction:kind};const label={pay:'付款',transfer:'转入',transferout:'转出',withdraw:'提现',fx:'兑换'}[kind];modal('确认'+label+'权限',`<div style="text-align:center;padding:10px 0 20px"><div class="result-icon" style="width:52px;height:52px;background:#ecf3ff;color:#5284cb">${icon('shield')}</div><h3>核验本次资金操作</h3><p class="tiny muted" style="margin-top:10px">企业管理员 · 杭州远帆贸易有限公司</p></div>${kv('操作类型',label)}${kv('验证方式','企业支付权限验证（模拟）')}${note('原型演示：点击下方按钮直接模拟验证通过，无需填写密码或验证码。')}<div class="error-text" id="modal-error"></div>`,b('取消','close-modal')+b('模拟验证通过，确认'+label,'verify-submit','primary',`data-kind="${kind}"`));}
function resultPreview(type,status='已完成'){const config={transferout:{type:'转出',title:'转出至 ACP',display:'− USD 1,000.00',native:1000,currency:'USD',source:'wallet',destination:'acp',fee:0,note:'钱包余额减少，ACP 同币种余额增加。此处为预览，余额不变。'},pay:{type:'付款',title:'1688 采购付款',display:'− CNY 120,150.00',amount:120150,fee:150,currency:'CNY',source:'wallet',order:'202611080126',q:M.quote(S,120000),note:'采购单更新为已付款，以下为结果页面预览，未实际改动演示余额。'},transfer:{type:'转入',title:'国际站余额转入',display:'+ USD 1,000.00',native:1000,currency:'USD',source:'intl',fee:0,note:'原账户减少，钱包增加。此结果为设计预览，演示余额不变。'},withdraw:{type:'提现',title:'提现至招商银行',display:'CNY 5,000.00',native:5000,currency:'CNY',source:'wallet',bank:'招商银行 · 6288',fee:2,note:'提现已提交，金额暂时占用。此处为设计预览，演示余额不变。'},fx:{type:'汇兑',title:'美元兑换人民币',display:'+ CNY 7,092.90',native:1000,received:7092.9,to:'CNY',currency:'USD',source:'wallet',fee:1,note:'卖出 USD 1,000.00，费用 USD 1.00。此结果为预览，余额不变。'}};nav(type==='transfer'?'transfer':type,{stage:3,record:{id:'DEMO-PREVIEW-'+type,time:'2026-11-08 14:30',status,preview:true,...config[type]}});}
function submitTransaction(kind){if(C.stage===3)return;if(kind==='transfer'){const amount=num('amount'),f=C.fields;M.transfer(S,f.source,f.currency,amount);addTx({type:'转入',title:S.accounts[f.source].name+'余额转入',detail:S.accounts[f.source].name+' → 跨境宝 · 内部调拨',display:'+ '+f.currency+' '+fmt(amount),native:amount,currency:f.currency,amount:M.round(amount*M.rates[f.currency]),fee:0,source:f.source,status:'已完成',note:'转出账户已扣减，跨境宝同币种余额已增加，三方合计资产保持不变。'});
}else if(kind==='transferout'){const f=C.fields,amount=num('amount');M.transferOut(S,f.destination,f.currency,amount);addTx({type:'转出',title:'转出至'+S.accounts[f.destination].name,detail:'跨境宝 → '+S.accounts[f.destination].name+' · 同币种划转',display:'− '+f.currency+' '+fmt(amount),native:amount,currency:f.currency,amount:M.round(amount*M.rates[f.currency]),fee:0,source:'wallet',destination:f.destination,status:'已完成',note:'跨境宝余额已扣减，'+S.accounts[f.destination].name+'同币种余额已增加。'});
}else if(kind==='withdraw'){const f=C.fields,amount=num('amount'),fee=f.currency==='CNY'?2:f.currency==='USD'?5:4,total=M.round(amount+fee),bank=S.banks.find(x=>x.id===f.bank&&x.currency===f.currency);if(!bank||!Number.isFinite(amount)||amount<=0||total>S.accounts.wallet.balances[f.currency])throw Error('提现金额或银行卡不可用');S.accounts.wallet.balances[f.currency]=M.round(S.accounts.wallet.balances[f.currency]-total);S.accounts.wallet.frozen[f.currency]=M.round(S.accounts.wallet.frozen[f.currency]+total);addTx({type:'提现',title:'提现至'+bank.name,detail:'跨境宝 → '+bank.name+' · '+bank.tail,display:f.currency+' '+fmt(amount),native:amount,amount:total,fee,currency:f.currency,source:'wallet',bank:bank.name+' · '+bank.tail,status:'处理中',settled:false,note:'提现金额和费用已占用，等待银行处理。演示预计 1–2 个工作日到账。'});
}else if(kind==='fx'){if(C.expired||Date.now()>C.expires)throw Error('报价已过期，请重新获取');const f=C.fields,amount=num('amount'),q=M.exchange(S,f.from,f.to,amount);addTx({type:'汇兑',title:f.from+' 兑换 '+f.to,detail:'跨境宝账户内 · '+f.from+' → '+f.to,display:'+ '+f.to+' '+fmt(q.received),native:amount,received:q.received,to:f.to,fee:q.fee,currency:f.from,source:'wallet',amount:amount*M.rates[f.from],status:'已完成',note:'卖出 '+f.from+' '+fmt(amount)+'，汇兑费用 '+f.from+' '+fmt(q.fee)+'，买入币种已记入跨境宝。'});}persist();closeModal();C.stage=3;render();window.scrollTo(0,0);}
function resolveRecord(success){const t=C.record;if(t.preview){toast('这是结果预览；返回起点完成交易后可查询真实演示状态。');return;}if(t.settled||!['处理中','待入账'].includes(t.status)){toast('这笔交易已处理完成，无需重复提交');return;}if(t.type==='付款'){M.settle(S,t.q,success);t.status=success?'已完成':'付款失败';t.note=success?'采购付款已完成，资金占用转为扣款，采购单已更新。':'渠道处理失败，原账户资金占用已全部释放，请调整后重新付款。';}else if(t.type==='提现'){const w=S.accounts.wallet;w.frozen[t.currency]=M.round(w.frozen[t.currency]-t.amount);if(!success)w.balances[t.currency]=M.round(w.balances[t.currency]+t.amount);t.status=success?'已完成':'已退回';t.note=success?'银行处理成功，资金已到达指定同名账户。':'银行返回：账户状态异常。提现金额及费用已释放，可更换银行卡后重新发起。';}else if(t.type==='转入'){if(success)S.accounts.wallet.balances[t.currency]=M.round(S.accounts.wallet.balances[t.currency]+t.native);t.status=success?'已完成':'已退回';t.note=success?'银行来款已完成匹配，跨境宝余额和可采购额度已更新。':'来款信息未匹配，未记入钱包余额，请核对汇款主体与附言。';}t.settled=true;persist();render();}
function scenarioPopover(){return `<div class="scenario-pop"><h3>选择一个情景</h3><p>切换页面与演示状态，重置可恢复初始数据。</p>${[['outshort','转出余额不足'],['unauth','国际站授权关闭'],['quoteexpired','汇兑报价过期'],['bankreturn','提现被银行退回'],['settings-off','授权开关与额度预览']].map(([id,n])=>`<button data-scenario="${id}">${n} <span style="margin-left:auto">→</span></button>`).join('')}</div>`;}
function runScenario(id){closeModal();popup=false;if(id==='binding-manage'){nav('settings');document.getElementById('linked-accounts')?.scrollIntoView({block:'start'});return;}if(id==='outshort'){nav('transferout',{stage:1,fields:{destination:'acp',currency:'USD',amount:'100000'},error:'转出金额超过跨境宝 USD 可用余额，请减少金额或先转入。'});return;}if(id==='outintl'){nav('transferout',{stage:1,fields:{destination:'intl',currency:'USD',amount:'1000'}});return;}if(id==='outdisabled'){S.accounts.acp.authorized=false;persist();nav('transferout',{stage:2,fields:{destination:'acp',currency:'USD',amount:'1000'}});return;}if(id==='unauth'){S.accounts.intl.authorized=false;persist();nav('transfer',{stage:1,fields:{source:'intl',currency:'USD',amount:'1000'}});return;}if(id==='pendingfunds'){nav('home');pendingFunds();return;}if(id==='bankpending'){nav('transfer',{stage:1,fields:{source:'bank',currency:'USD',amount:'1000'}});return;}if(id==='quoteexpired'){nav('fx',{stage:1,expired:true,expires:0,fields:{from:'USD',to:'CNY',amount:'1000'}});return;}if(id==='withdrawshort'){nav('withdraw',{fields:{currency:'CNY',bank:'b1',amount:'500000'},error:'预计扣除金额超出该币种可用余额，请减少金额或先转入。'});return;}if(id==='nobank'){nav('withdraw',{fields:{currency:'EUR',bank:'',amount:'100'}});return;}if(id==='bankreturn'){nav('withdraw');toast('提交提现后，点击“模拟银行退回”查看资金释放。');return;}if(id==='fxshort'){nav('fx',{fields:{from:'USD',to:'CNY',amount:'500000'},error:'卖出金额超过 USD 可用余额。'});return;}if(id==='samecurrency'){nav('fx',{fields:{from:'USD',to:'USD',amount:'1000'},error:'请选择不同币种。'});return;}nav('settings');if(id==='settings-off')C.authDraft.intl=false;if(id==='settings-order')C.draft.order=['acp','wallet','intl'];render();}
function pendingFunds(){modal('国际站待结算资金',`${kv('关联外销订单','TA202611070016')}${kv('待结算金额','USD 3,000.00','total')}${note('客户已付款，资金尚未达到可支配状态，暂不计入可采购额度。','warn')}<div class="timeline"><div class="timeline-item">客户付款成功<p>已记录订单收款</p></div><div class="timeline-item">等待满足结算条件<p>当前状态，尚不可采购或转出</p></div><div class="timeline-item">结算后成为可用余额<p>按已设置的入账位置处理</p></div></div><p class="tiny muted">此处仅展示状态，具体结算条件与时间由渠道返回。</p>`,b('查看账户余额','go-home','primary'),true);}

function flowJump(id,index){if(['transfer','transferout'].includes(id)){if(index===3)resultPreview(id);else nav(id,{stage:index,fields:id==='transfer'?{source:'intl',currency:'USD',amount:'1000'}:{destination:'acp',currency:'USD',amount:'1000'}});}else if(id==='withdraw'){if(index===3)resultPreview('withdraw','处理中');else nav('withdraw',{stage:index===2?1:0});}else if(id==='fx'){if(index===3)resultPreview('fx');else nav('fx',{stage:index===2?1:0,expires:Date.now()+30000,expired:false});}else if(id==='settings'){nav('settings');if(index===2){C.authDraft.intl=false;render();}if(index===3)toast('调整顺序或授权后点击保存，对新交易生效。');}}
function fail(message){C.error=message;render();return false;}
function saveSettings(){commitSettings();}
function commitSettings(){S.settings=JSON.parse(JSON.stringify(C.draft));for(const id of ['wallet','acp','intl'])S.accounts[id].authorized=!!C.authDraft[id];persist();closeModal();C.error='';render();toast('支付顺序与授权已保存，可采购额度已更新');}
function refreshAmountInput(target){const start=target.selectionStart,end=target.selectionEnd,name=target.name;render();const node=document.getElementById(name);node?.focus();try{node?.setSelectionRange(start,end);}catch{}}
document.addEventListener('input',e=>{const t=e.target;if(t.closest('#overlay'))return;if(t.dataset.setting){C.draft[t.dataset.setting]=t.value;return;}if(!t.name)return;C.fields[t.name]=t.type==='checkbox'?t.checked:t.value;C.error='';if(C.page==='pay'&&C.stage===1&&t.name==='amount'){C.fields.agreed=false;refreshAmountInput(t);}if(C.page==='withdraw'&&C.stage===0&&t.name==='amount')refreshAmountInput(t);if(C.page==='fx'&&C.stage===0&&t.name==='amount'){const q=fxCalc();$('#fx-received').innerHTML=fmt(q.received)+` <small style="font-size:14px;color:#7790b0">${C.fields.to}</small>`;$('#fx-fee').textContent=C.fields.from+' '+fmt(q.fee);}});
document.addEventListener('change',e=>{const t=e.target;if(t.closest('#overlay'))return;if(t.dataset.route){C.draft.route[t.dataset.route]=t.value;return;}if(t.name&&!t.dataset.setting){C.fields[t.name]=t.type==='checkbox'?t.checked:t.value;C.error='';if(t.name==='agreed')return;if(C.page==='withdraw'&&t.name==='currency')C.fields.bank=S.banks.find(b=>b.currency===t.value)?.id||'';if(t.tagName==='SELECT')render();}});
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-action],[data-scenario]');if(!el||el.disabled)return;if(el.dataset.nav){closeModal();nav(el.dataset.nav);return;}if(el.dataset.mode){C.mode=el.dataset.mode;popup=false;render();window.scrollTo(0,0);return;}if(el.dataset.flowtab){C.flow=el.dataset.flowtab;render();return;}if(el.dataset.paytab){C.tab=el.dataset.paytab;C.fields=C.tab==='other'?{supplier:'深圳市远航包装有限公司',recipient:'DEMO **** 9316',order:'PO202611080021',amount:'18000',purpose:'包装材料采购'}:{};render();return;}if(el.dataset.settingtab){C.tab=el.dataset.settingtab;C.error='';render();return;}if(el.dataset.scenario){runScenario(el.dataset.scenario);return;}const a=el.dataset.action;if(!a)return;if(bindingAction(a,el))return;
if(a==='close-modal'){closeModal();return;}if(a.startsWith('go-')){closeModal();const dest=a.slice(3);nav(['accounts','auto','card'].includes(dest)?'settings':dest);return;}

if(a==='privacy'){C.privacy=!C.privacy;render();return;}if(a==='quota'){quotaDrawer();return;}if(a==='account'){accountDrawer(el.dataset.id);return;}if(a==='pending-funds'){pendingFunds();return;}if(a==='scenario'){popup=!popup;render();return;}if(a==='flow-jump'){flowJump(el.dataset.flow,Number(el.dataset.step));return;}if(a==='profile'){modal('当前商家账户',`${kv('企业名称','杭州远帆贸易有限公司（演示）')}${kv('当前角色','企业管理员')}${kv('关联渠道','国际站、ACP、跨境宝')}${note('所有商家、账户和交易信息都是为产品评审构造的演示数据。')}`,b('完成','close-modal','primary'));return;}if(a==='notifications'){pendingFunds();return;}

if(a==='reset'){modal('重置演示数据',`<p style="font-size:13px;color:#788aa3">恢复初始余额、支付管理、银行卡与演示账单，清除本次原型中进行的模拟操作。</p>`,b('取消','close-modal')+b('重置演示','reset-confirm','primary'));return;}if(a==='reset-confirm'){returnToPay=null;S=M.seed();persist();closeModal();nav('home');toast('已恢复初始演示数据');return;}
if(a==='out-select'){C.fields={destination:el.dataset.id,currency:'USD',amount:'1000'};C.stage=1;C.error='';render();return;}if(a==='out-back'){nav('transferout');return;}if(a==='out-next'){const amt=num('amount'),f=C.fields;if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的转出金额，最多两位小数。');if(amt>S.accounts.wallet.balances[f.currency])return fail('转出金额超过跨境宝该币种的可用余额。请减少金额或先转入。');C.stage=2;C.error='';render();return;}if(a==='out-edit'){C.stage=1;C.error='';render();return;}if(a==='out-confirm'){verify('transferout');return;}
if(a==='transfer-select'){C.fields={source:el.dataset.id,currency:'USD',amount:'1000'};C.stage=1;C.error='';render();return;}if(a==='transfer-back'){nav('transfer');return;}if(a==='transfer-next'){const amt=num('amount'),f=C.fields;if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的转入金额，最多两位小数。');if(!S.accounts[f.source].authorized)return fail('请先授权使用该资金来源。');if(amt>S.accounts[f.source].balances[f.currency])return fail('转入金额超过该币种可用余额，冻结和待结算资金不能转入。');C.stage=2;C.error='';render();return;}if(a==='transfer-edit'){C.stage=1;C.error='';render();return;}if(a==='transfer-confirm'){verify('transfer');return;}if(a==='auth-source'){nav('settings');return;}
if(a==='bank-intent'){const amt=num('amount'),f=C.fields;if(!Number.isFinite(amt)||amt<=0)return fail('请输入有效的计划转入金额。');addTx({type:'转入',title:'银行汇款转入',detail:'演示银行 → 跨境宝 · 待核对入账',display:f.currency+' '+fmt(amt),native:amt,currency:f.currency,amount:amt*M.rates[f.currency],fee:0,source:'bank',status:'待入账',settled:false,note:'已记录转入意向，当前余额未增加。银行来款完成匹配后才可使用。'});C.stage=3;render();return;}if(a==='copy-bank'){const str='【原型演示，不可实际汇款】杭州远帆贸易有限公司 · 演示银行 · DEMO **** 8632 · 附言 DEMO-YF-20261108';if(navigator.clipboard)navigator.clipboard.writeText(str).then(()=>toast('已复制演示收款信息')).catch(()=>modal('收款信息',`<p class="tiny">${str}</p>`,b('关闭','close-modal')));else modal('收款信息',`<p class="tiny">${str}</p>`,b('关闭','close-modal'));return;}if(a==='new-channel'){closeModal();nav('transfer',{stage:1,fields:{source:'channel',channelName:'海外独立站',merchant:'DEMO-YF001',channelRoute:'wallet'}});return;}if(a==='channel-connect'){const name=(C.fields.channelName??'海外独立站').trim(),merchant=(C.fields.merchant??'DEMO-YF001').trim();if(!name||!merchant)return fail('请填写渠道名称与演示商户号。');if(S.channels.some(x=>x.name===name))return fail('已连接同名渠道，请在资金来源中查看或使用不同名称。');S.channels.push({name,merchant,route:C.fields.channelRoute||'wallet'});persist();nav('transfer');toast('新渠道已连接（演示），未增加资产或可采购额度');return;}
if(a==='max'){const f=C.fields;if(C.page==='transferout')f.amount=String(S.accounts.wallet.balances[f.currency]);if(C.page==='transfer')f.amount=String(S.accounts[f.source]?.balances[f.currency]||0);if(C.page==='withdraw'){const fee=f.currency==='CNY'?2:f.currency==='USD'?5:4;f.amount=String(Math.max(0,M.round(S.accounts.wallet.balances[f.currency]-fee)));}if(C.page==='fx')f.amount=String(S.accounts.wallet.balances[f.from]);C.error='';render();return;}

if(a==='banks'){bankModal();return;}if(a==='add-bank'){addBankModal();return;}if(a==='bank-add-confirm'){const name=$('#bank-name').value.trim(),currency=$('#bank-currency').value,tail=$('#bank-tail').value.trim();if(!name||!/^\d{4}$/.test(tail)){$('#modal-error').textContent='请填写银行名称和 4 位数字尾号。';return;}if(S.banks.some(x=>x.name===name&&x.tail===tail&&x.currency===currency)){$('#modal-error').textContent='该银行卡已存在，请勿重复添加。';return;}const id='b'+Date.now();S.banks.push({id,name,currency,tail,status:'可用'});persist();if(C.page==='withdraw'){C.fields.currency=currency;C.fields.bank=id;}closeModal();render();toast('银行卡已验证并添加（演示）');return;}if(a==='select-bank'){C.fields.bank=el.dataset.id;render();return;}if(a==='withdraw-next'){const f=C.fields,amt=num('amount'),fee=f.currency==='CNY'?2:f.currency==='USD'?5:4;if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的提现金额，最多两位小数。');if(!S.banks.some(b=>b.id===f.bank&&b.currency===f.currency))return fail('请先选择支持此币种的银行卡。');if(M.round(amt+fee)>S.accounts.wallet.balances[f.currency])return fail('提现金额加服务费超过该币种可用余额。最多可到账 '+f.currency+' '+fmt(Math.max(0,S.accounts.wallet.balances[f.currency]-fee))+'。');C.stage=1;C.error='';render();return;}if(a==='withdraw-edit'){C.stage=0;render();return;}if(a==='withdraw-confirm'){verify('withdraw');return;}
if(a==='swap-fx'){const f=C.fields;[f.from,f.to]=[f.to,f.from];C.error='';render();return;}if(a==='fx-next'||a==='fx-refresh'){const f=C.fields,amt=num('amount');if(f.from===f.to)return fail('请选择不同的卖出和买入币种。');if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的卖出金额，最多两位小数。');if(amt>S.accounts.wallet.balances[f.from])return fail('卖出金额超出 '+f.from+' 可用余额。');C.stage=1;C.expires=Date.now()+30000;C.expired=false;C.error='';render();return;}if(a==='fx-edit'){C.stage=0;C.error='';render();return;}if(a==='fx-confirm'){if(C.expired||Date.now()>C.expires){C.expired=true;render();return;}verify('fx');return;}
if(a==='verify-submit'){try{submitTransaction(el.dataset.kind);}catch(err){const msg=err.message||'交易未完成，请检查后重试。';closeModal();C.error=msg;if(el.dataset.kind==='fx')C.expired=true;render();}return;}if(a==='resolve-tx'){resolveRecord(el.dataset.outcome!=='fail');return;}if(a==='again'){nav(C.page);return;}if(a==='tx'){txDrawer(el.dataset.id);return;}if(a==='show-tx-result'){const t=S.tx.find(x=>x.id===el.dataset.id)||C.record;closeModal();nav(({付款:'pay',转入:'transfer',转出:'transferout',提现:'withdraw',汇兑:'fx'})[t.type]||'home',{stage:3,record:t});return;}
if(a==='authorization-toggle'){const id=el.dataset.id;if(id!=='wallet'){C.authDraft[id]=!C.authDraft[id];render();}return;}if(a==='setting-toggle'){const key=el.dataset.key;C.draft[key]=!C.draft[key];render();return;}if(a==='move-source'){const i=Number(el.dataset.index),j=i+Number(el.dataset.dir),order=C.draft.order;if(j>=0&&j<order.length)[order[i],order[j]]=[order[j],order[i]];render();return;}if(a==='settings-save'){saveSettings();return;}if(a==='settings-commit'){commitSettings();return;}if(a==='settings-cancel'){C.draft=JSON.parse(JSON.stringify(S.settings));C.authDraft={wallet:true,acp:S.accounts.acp.authorized,intl:S.accounts.intl.authorized};C.error='';render();toast('已恢复当前保存的设置');return;}if(a==='permissions'){modal('操作权限说明',`${kv('查看者','查看余额、账户和交易明细')}${kv('经办人','发起转入、付款、提现、汇兑')}${kv('审批人','确认超限付款及指定资金操作')}${kv('企业管理员','管理资金来源、银行卡和自动付款授权')}${note('正式权限矩阵与审批阈值待业务确认；原型当前使用企业管理员身份。')}`,b('知道了','close-modal','primary'));return;}
if(['account-records','transfer-records','transferout-records','fx-records'].includes(a)){closeModal();nav('records',{fields:{type:a==='transferout-records'?'转出':a==='transfer-records'?'转入':a==='fx-records'?'汇兑':'all'}});return;}if(a==='records-search'){render();return;}if(a==='records-reset'){C.fields={};render();return;}if(a==='export'){const rows=[['交易流水','交易名称','时间','账户','原币金额','状态','备注'],...filteredTx().map(t=>[t.id,t.title,t.time,S.accounts[t.source]?.name||'银行',t.display,t.status,t.note||''])];const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='跨境宝_演示资金明细.csv';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出演示资金明细');return;}if(a==='fee-info'){modal('采购服务费说明',`${kv('演示费率','0.125%')}${kv('示例货款','CNY 120,000.00')}${kv('服务费','CNY 150.00')}${kv('合计应付','CNY 120,150.00','total')}${note('费用用于产品流程演示。正式费率、优惠和多渠道费用以接入方规则为准。')}`,b('知道了','close-modal','primary'));return;}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.frame'))e.target.click();if(e.key==='Escape'){closeModal();if(popup){popup=false;render();}}if(e.key==='Tab'&&$('#overlay').children.length){const nodes=[...$('#overlay').querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
let dragged=null;document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-source]');if(row)dragged=row.dataset.source;});document.addEventListener('dragover',e=>{if(e.target.closest('[data-source]'))e.preventDefault();});document.addEventListener('drop',e=>{const row=e.target.closest('[data-source]');if(!row||!dragged||!C.draft)return;e.preventDefault();const order=C.draft.order,from=order.indexOf(dragged),to=order.indexOf(row.dataset.source);order.splice(from,1);order.splice(to,0,dragged);dragged=null;render();});
setInterval(()=>{if(C.page==='fx'&&C.mode==='app'&&C.stage===1&&!C.expired){const remaining=Math.max(0,Math.ceil((C.expires-Date.now())/1000));if(remaining<=0){C.expired=true;render();}else if($('#quote-timer'))$('#quote-timer').textContent='报价有效 '+remaining+' 秒';}},1000);
const initial=location.hash.slice(1);fresh(navs.some(x=>x[0]===initial)||initial==='settings'?initial:'home');
